/// <summary>
/// desigmed from AVA
/// </summary>
protected void setSalesPrice()
{
    boolean isUpdateNeeded = true;
    SalesTable      salesTable = SalesLine.salesTable();
   // if (this.isFieldSet(fieldNum(SalesLine, SalesPrice)))
    if (salesLine.SystemEntrySource == PriceDiscSystemSource::CopyFromSalesOrder)
    {
        isUpdateNeeded = false;
    }


    next setSalesPrice();

    if (isUpdateNeeded)
    {

        AxSalesLine     localSalesLine = this.axOrig() as AxSalesLine;
        SalesLine       locSalesLineRecord =localSalesLine.currentRecord();
        if (salesTable.IntercompanyOrder)
        {
            if (salesTable.custTable_CustAccount().interCompanyTradingPartner().interCompanyEndpointActionPolicy().PriceDiscountSearch == NoYes::Yes)
            {
                if(AVASalesParameters::find().PriceSearch)
                {

                    if (salesLine.AVAItemSetComponent == NoYes::No)
                    {

                        locSalesLineRecord.AVApriceCalculation();
                        this.parmSalesPrice(locSalesLineRecord.SalesPrice);
                    }
                }
            }
        }
        else
        {
            if(AVASalesParameters::find().PriceSearch)
            {

                if (salesLine.AVAItemSetComponent == NoYes::No)
                {

                    locSalesLineRecord.AVApriceCalculation();
                    this.parmSalesPrice(locSalesLineRecord.SalesPrice);
                }
            }
        }
    }

    if (salesLine.AVAItemSetComponent == NoYes::Yes)
    {
        this.parmSalesPrice(0);
        this.parmLinePercent(0);
    }


}

