public NDXPAInfo parmAVAPAInfo(NDXPAInfo _parmValue = '')
{
    if (!prmisDefault(_parmValue))
    {
        this.setField(fieldNum(SalesLine, NDX_PAInfo), _parmValue);
    }

    return salesLine.NDX_PAInfo;
}
